mapper.select:
SELECT /* QueryID : com.demo.proworks.attendance.selectListAttendance */ RECORD_ID as recordId, SESSION_ID as sessionId, NAME as name, EMAIL as email, IP_ADDRESS as ipAddress, JOIN_TIME as joinTime, LEAVE_TIME as leaveTime FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT * FROM ATTENDANCE_RECORD WHERE 1=1
AND SESSION_ID like '%${scSessionId}%'
AND NAME like '%${scName}%'
AND EMAIL like '%${scEmail}%'
AND JOIN_TIME like '%${scJoinTime}%'
) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}

SELECT record_id, session_id, name, email, COALESCE(ip_address, '') as ip_address, DATE_FORMAT(join_time, '%Y-%m-%d %H:%i:%s') as join_time, CASE WHEN leave_time IS NOT NULL THEN DATE_FORMAT(leave_time, '%Y-%m-%d %H:%i:%s') ELSE '진행중' END as leave_time, CASE WHEN leave_time IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, join_time, leave_time) ELSE '-' END as participation_minutes, CASE WHEN leave_time IS NULL THEN '참여중' ELSE '퇴장완료' END as status FROM attendance_records WHERE 1=1
AND session_id = #{scSessionId}
AND name LIKE CONCAT('%', #{scName}, '%')
AND email LIKE CONCAT('%', #{scEmail}, '%')
AND DATE(join_time) = #{scJoinTime}
ORDER BY join_time ASC

SELECT COUNT(*)
FROM attendance_records
WHERE session_id = #{sessionId}
AND email = #{email}

	AND record_id != #{recordId}

